new Handsontable(container, {
  startRows: 5,
  startCols: 5,
  rowHeaders: true,
  colHeaders: true,
  theme: { ...mainTheme, colorScheme: 'light' },
  licenseKey: 'non-commercial-and-evaluation',
});
